  color: #0a111c; font-family: var(--serif); font-size: 24px; letter-spacing: .1em; text-transform: uppercase;
  box-shadow: 0 7px 30px rgba(190,146,75,.22), inset 0 1px 0 rgba(255,255,255,.34); transition: .18s ease;
}
.play-button:hover { background: linear-gradient(100deg, #f0d291, #b98d4d); box-shadow: 0 8px 38px rgba(221,180,105,.38); transform: translateY(-1px); }
.play-rune { font-size: 17px; opacity: .66; }
.play-button small { font-family: var(--sans); font-size: 8px; letter-spacing: .18em; opacity: .58; text-transform: uppercase; }
.menu-footnote { margin-top: 13px; text-align: center; font-size: 7.5px; letter-spacing: .1em; color: rgba(190,206,226,.37); }
.menu-footer { position: relative; z-index: 2; display: flex; justify-content: space-between; padding: 22px 44px 24px; font-size: 7px; letter-spacing: .22em; color: rgba(188,205,225,.32); }
.footer-controls { display: flex; align-items: center; gap: 8px; }
.footer-controls i { width: 5px; height: 5px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 8px var(--gold); }

/* ============ LOADING ============ */
#loading { z-index: 40; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 40%, #13243a, #050a12 68%); }
.loading-inner { text-align: center; width: min(420px, 80vw); }
.loading-cat { font-size: 38px; color: var(--gold); opacity: .8; margin-bottom: 18px; animation: breathe 2.6s ease-in-out infinite; }
.loading-title { font-family: var(--serif); font-size: 13px; letter-spacing: .28em; color: var(--muted); }
.loading-bar { height: 2px; background: rgba(255,255,255,.09); margin: 22px 0 14px; overflow: hidden; }
.loading-bar i { display: block; height: 100%; width: 10%; background: linear-gradient(90deg, var(--gold-deep), var(--gold-bright)); transition: width .3s; }
.loading-tip { font-family: var(--serif); font-size: 12px; color: var(--faint); font-style: italic; }
@keyframes breathe { 0%,100% { opacity: .5; transform: translateY(0); } 50% { opacity: 1; transform: translateY(-4px); } }

/* ============ HUD ============ */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
#hud button { pointer-events: auto; }
.hud-top-left { position: absolute; top: 22px; left: 24px; display: flex; align-items: center; gap: 13px; filter: drop-shadow(0 2px 8px rgba(0,0,0,.6)); }
.level-medallion {
  width: 54px; height: 60px; position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center;
  background: radial-gradient(ellipse at 50% 38%, rgba(45,63,86,.92), rgba(9,17,29,.94));
  border: 1px solid rgba(216,184,120,.43); clip-path: polygon(0 10%, 18% 0, 50% 7%, 82% 0, 100% 10%, 96% 82%, 50% 100%, 4% 82%);
}
.level-medallion::before { content: ""; position: absolute; inset: 3px; border: 1px solid rgba(216,184,120,.18); clip-path: inherit; }
.level-medallion span { font-family: var(--serif); font-size: 24px; line-height: 1; color: var(--gold-bright); }
.level-medallion small { font-size: 6px; letter-spacing: .22em; color: var(--faint); margin-top: 2px; }
.vitals { width: 250px; }
.cat-line { display: flex; align-items: baseline; gap: 9px; margin: 0 0 5px 2px; text-shadow: 0 2px 6px #000; }
.cat-line span { font-family: var(--serif); font-size: 15px; letter-spacing: .09em; }
.cat-line em { font-style: normal; font-size: 7px; letter-spacing: .2em; text-transform: uppercase; color: var(--gold); opacity: .8; }
.bar { display: flex; align-items: center; gap: 6px; height: 13px; margin-bottom: 3px; }
.bar-icon { width: 12px; text-align: center; font-size: 9px; opacity: .76; }
.bar-track { position: relative; flex: 1; height: 7px; background: rgba(3, 8, 16, .75); border: 1px solid rgba(205,226,247,.18); box-shadow: inset 0 1px 3px rgba(0,0,0,.6); overflow: hidden; }
.bar-track i { display: block; height: 100%; width: 100%; transition: width .18s; }
.bar.health .bar-track i { background: linear-gradient(90deg, #7b242c, #ca5657 55%, #e2766d); }
.bar.stamina .bar-track i { background: linear-gradient(90deg, #7f6b27, #c5a94e 60%, #e0c96f); }
.bar.mana .bar-track i { background: linear-gradient(90deg, #2d4c83, #5a8cc7 55%, #8abde8); }
.bar b { width: 25px; font-size: 8px; font-weight: 400; color: rgba(226,236,248,.62); text-align: right; }
.health .bar-icon { color: #d97070; } .stamina .bar-icon { color: #d9c06d; } .mana .bar-icon { color: #85b8e5; }

.compass-wrap { position: absolute; top: 17px; left: 50%; transform: translateX(-50%); width: min(420px, 34vw); text-align: center; filter: drop-shadow(0 2px 7px rgba(0,0,0,.8)); }
.compass { position: relative; height: 28px; overflow: hidden; border-top: 1px solid rgba(213,231,249,.2); border-bottom: 1px solid rgba(213,231,249,.12); background: linear-gradient(90deg, transparent, rgba(7,15,27,.55) 18%, rgba(7,15,27,.55) 82%, transparent); }
.compass::before, .compass::after { content: ""; position: absolute; top: 0; bottom: 0; width: 35%; z-index: 2; pointer-events: none; }
.compass::before { left: 0; background: linear-gradient(90deg, rgba(5,12,22,.9), transparent); } .compass::after { right: 0; background: linear-gradient(-90deg, rgba(5,12,22,.9), transparent); }
.compass-strip { display: flex; justify-content: space-between; padding: 8px 30px 0; font-family: var(--serif); font-size: 9px; letter-spacing: .15em; color: rgba(227,238,250,.52); transition: transform .1s linear; }
.compass-strip span:nth-child(odd) { color: rgba(227,238,250,.34); font-size: 7px; }
.compass-strip span:nth-child(3) { color: var(--gold-bright); font-size: 11px; }
.compass-needle { position: absolute; left: 50%; bottom: 0; width: 1px; height: 7px; background: var(--gold); z-index: 3; box-shadow: 0 0 7px var(--gold); }
.compass-zone { margin-top: 4px; font-size: 7px; letter-spacing: .28em; color: rgba(219,234,251,.42); }

.hud-top-right { position: absolute; top: 20px; right: 22px; display: flex; flex-direction: column; align-items: flex-end; gap: 11px; }
.map-frame { position: relative; width: 132px; height: 132px; border-radius: 50%; background: rgba(7,15,27,.55); box-shadow: 0 3px 20px rgba(0,0,0,.45), inset 0 0 0 1px rgba(212,230,248,.2); }
#minimap { width: 100%; height: 100%; border-radius: 50%; opacity: .92; }
.map-ring { position: absolute; inset: 5px; border-radius: 50%; border: 1px solid rgba(216,184,120,.3); pointer-events: none; }
.map-ring::before { content: ""; position: absolute; inset: 8px; border-radius: 50%; border: 1px dashed rgba(203,224,245,.13); }
.map-n { position: absolute; top: -2px; left: 50%; transform: translateX(-50%); font-family: var(--serif); font-size: 8px; color: var(--gold); background: #0a1421; padding: 0 4px; }
.map-expand { position: absolute; bottom: -3px; right: -2px; width: 25px; height: 25px; border-radius: 50%; border: 1px solid rgba(216,184,120,.4); background: rgba(9,18,31,.92); color: var(--gold); font-size: 13px; line-height: 1; }
.quest-tracker { width: 226px; padding: 11px 13px 12px; background: linear-gradient(135deg, rgba(10,19,33,.78), rgba(11,20,34,.5)); border-left: 2px solid rgba(216,184,120,.68); box-shadow: 0 3px 20px rgba(0,0,0,.22); backdrop-filter: blur(6px); }
.quest-kicker { display: flex; align-items: center; gap: 7px; font-size: 6.5px; letter-spacing: .24em; color: var(--gold); opacity: .9; margin-bottom: 5px; }
.quest-kicker span { width: 4px; height: 4px; border: 1px solid var(--gold); transform: rotate(45deg); }
.quest-title { font-family: var(--serif); font-size: 14px; color: #e9eff7; letter-spacing: .03em; margin-bottom: 3px; }
.quest-step { font-size: 9px; line-height: 1.45; color: rgba(205,220,238,.63); }
.quest-dist { font-size: 8px; letter-spacing: .1em; color: rgba(216,184,120,.65); margin-top: 6px; }

.crosshair { position: absolute; left: 50%; top: 50%; width: 24px; height: 24px; transform: translate(-50%,-50%); opacity: .72; transition: opacity .2s, transform .2s; }
.crosshair i { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; transform: translate(-50%,-50%); border-radius: 50%; background: rgba(242,247,255,.88); box-shadow: 0 0 5px rgba(0,0,0,.8); }
.crosshair b { position: absolute; inset: 6px; border: 1px solid rgba(231,241,252,.2); border-radius: 50%; }
.crosshair.hidden { opacity: 0; }
.crosshair.active { transform: translate(-50%,-50%) scale(1.4); opacity: 1; }
.crosshair.active b { border-color: rgba(216,184,120,.8); }

.interact-prompt { position: absolute; left: 50%; bottom: 142px; transform: translateX(-50%); display: flex; align-items: center; gap: 9px; padding: 7px 13px 7px 8px; border: 1px solid rgba(216,184,120,.35); background: rgba(7,15,27,.85); backdrop-filter: blur(8px); box-shadow: 0 5px 20px rgba(0,0,0,.4); font-family: var(--serif); font-size: 12px; letter-spacing: .05em; color: #e7eef7; }
kbd { display: inline-flex; align-items: center; justify-content: center; min-width: 19px; height: 19px; padding: 0 4px; border: 1px solid rgba(211,229,247,.3); border-radius: 2px; background: rgba(220,235,250,.09); color: rgba(240,246,253,.88); font-family: var(--sans); font-size: 8px; }
.interact-prompt kbd { border-color: rgba(216,184,120,.6); color: var(--gold-bright); background: rgba(216,184,120,.09); }
.loot-toast { position: absolute; left: 50%; top: 24%; transform: translateX(-50%); padding: 8px 18px; background: rgba(8,16,29,.84); border-top: 1px solid rgba(216,184,120,.48); border-bottom: 1px solid rgba(216,184,120,.18); font-family: var(--serif); font-size: 13px; color: var(--gold-bright); letter-spacing: .05em; animation: toastIn .3s ease both; text-align: center; }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, 8px); } to { opacity: 1; transform: translate(-50%, 0); } }
.location-title { position: absolute; left: 50%; top: 22%; transform: translateX(-50%); text-align: center; text-shadow: 0 2px 20px #000; animation: locIn 5s ease both; }
.location-title small { display: block; font-size: 7px; letter-spacing: .38em; color: var(--gold); margin-bottom: 6px; }
.location-title span { font-family: var(--serif); font-size: clamp(22px, 3vw, 36px); letter-spacing: .08em; color: #f0f4f8; }
@keyframes locIn { 0% { opacity: 0; transform: translate(-50%, 10px); } 15%, 70% { opacity: 1; transform: translate(-50%, 0); } 100% { opacity: 0; transform: translate(-50%, -4px); } }
.damage-flash { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(ellipse at center, transparent 25%, rgba(126,20,28,.55) 100%); transition: opacity .35s; }
.damage-flash.on { opacity: 1; transition: opacity .04s; }
.frost-overlay { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(ellipse at center, transparent 42%, rgba(144,191,226,.2) 80%, rgba(194,225,247,.36) 100%); transition: opacity 1s; }

.hud-bottom-left { position: absolute; left: 24px; bottom: 22px; display: flex; flex-direction: column; gap: 8px; filter: drop-shadow(0 2px 8px rgba(0,0,0,.7)); }
.gold-pill { display: flex; align-items: center; gap: 5px; width: fit-content; padding: 4px 9px 4px 7px; background: rgba(8,16,29,.64); border: 1px solid rgba(216,184,120,.22); font-size: 11px; }
.gold-pill span { color: var(--gold); font-size: 9px; } .gold-pill b { font-family: var(--serif); font-weight: 400; color: var(--gold-bright); } .gold-pill small { color: var(--faint); font-size: 7px; letter-spacing: .1em; }
.hint-line { font-size: 7px; letter-spacing: .05em; color: rgba(207,221,239,.36); display: flex; gap: 5px; align-items: center; }
.hint-line kbd { height: 15px; min-width: 15px; font-size: 6px; }

.hud-bottom-center { position: absolute; left: 50%; bottom: 20px; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 6px; }
.hotbar { display: flex; gap: 4px; padding: 5px; background: linear-gradient(180deg, rgba(15,27,44,.82), rgba(6,13,24,.9)); border: 1px solid rgba(206,226,247,.16); box-shadow: 0 4px 24px rgba(0,0,0,.48), inset 0 1px 0 rgba(255,255,255,.05); }
.slot { position: relative; width: 47px; height: 51px; border: 1px solid rgba(198,219,242,.1); background: rgba(19,33,52,.5); color: rgba(219,232,247,.48); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; transition: .15s; }
.slot:hover { border-color: rgba(216,184,120,.4); background: rgba(35,50,72,.7); }
.slot.selected { border-color: rgba(216,184,120,.72); background: linear-gradient(180deg, rgba(99,80,46,.44), rgba(20,33,51,.8)); color: var(--gold-bright); box-shadow: inset 0 0 15px rgba(216,184,120,.1), 0 0 8px rgba(216,184,120,.09); }
.slot-icon { font-family: var(--serif); font-size: 17px; line-height: 1; }
.slot b { position: absolute; top: 2px; left: 4px; font-size: 6px; font-weight: 400; color: rgba(217,231,248,.45); }
.slot small { font-size: 6px; letter-spacing: .04em; color: inherit; opacity: .62; }
.slot.spell .slot-icon { color: #8ec2ea; }
.slot.spell.selected .slot-icon { color: #b6defa; }
.spell-cost { font-family: var(--serif); font-size: 8px; font-style: italic; color: rgba(208,224,242,.34); letter-spacing: .04em; }

.hud-bottom-right { position: absolute; right: 24px; bottom: 23px; display: flex; gap: 7px; }
.round-action { width: 42px; height: 42px; border-radius: 50%; border: 1px solid rgba(203,224,245,.2); background: rgba(8,16,29,.67); color: rgba(228,239,251,.72); display: flex; flex-direction: column; align-items: center; justify-content: center; font-size: 13px; line-height: 1; backdrop-filter: blur(6px); transition: .15s; }
.round-action small { font-size: 5px; letter-spacing: .08em; color: var(--faint); margin-top: 2px; }
.round-action:hover { border-color: rgba(216,184,120,.5); color: var(--gold-bright); }

.crosshair-tip { position: absolute; left: 50%; top: calc(50% + 28px); transform: translateX(-50%); font-size: 8px; letter-spacing: .12em; color: rgba(225,238,251,.5); text-shadow: 0 1px 4px #000; }
.companion-card { position: absolute; right: 24px; bottom: 78px; display: flex; gap: 9px; align-items: center; padding: 8px 11px; background: rgba(8,16,29,.7); border: 1px solid rgba(174,205,233,.18); backdrop-filter: blur(6px); }
.companion-paw { font-size: 17px; color: var(--gold); }
.companion-card b { display: block; font-family: var(--serif); font-size: 11px; font-weight: 400; }
.companion-card small { display: block; font-size: 6px; letter-spacing: .12em; color: var(--faint); margin-top: 2px; }

/* ============ MOBILE ============ */
.mobile-controls { display: none; }
@media (pointer: coarse), (max-width: 820px) {
  .mobile-controls { display: block; position: absolute; inset: 0; pointer-events: none; }
  .joystick { position: absolute; left: max(17px, env(safe-area-inset-left)); bottom: max(28px, env(safe-area-inset-bottom)); width: 112px; height: 112px; border-radius: 50%; border: 1px solid rgba(220,235,251,.2); background: radial-gradient(circle, rgba(10,20,35,.18) 30%, rgba(10,20,35,.45)); box-shadow: inset 0 0 30px rgba(0,0,0,.2); pointer-events: auto; touch-action: none; }
  .joystick::before { content: ""; position: absolute; inset: 17px; border-radius: 50%; border: 1px dashed rgba(216,184,120,.18); }
  .joystick-knob { position: absolute; left: 50%; top: 50%; width: 45px; height: 45px; margin: -22px; border-radius: 50%; border: 1px solid rgba(216,184,120,.48); background: radial-gradient(circle at 40% 32%, rgba(255,255,255,.18), rgba(18,31,49,.75)); box-shadow: 0 2px 9px rgba(0,0,0,.4); }
  .joystick span { position: absolute; bottom: 8px; left: 50%; transform: translateX(-50%); font-size: 5px; letter-spacing: .18em; color: rgba(207,224,243,.3); }
  .look-zone { position: absolute; inset: 0 0 0 40%; pointer-events: none; display: flex; align-items: flex-end; justify-content: center; padding-bottom: 156px; }
  .look-zone span { font-size: 5px; letter-spacing: .18em; color: rgba(207,224,243,.18); }
  .touch-actions { position: absolute; right: max(15px, env(safe-area-inset-right)); bottom: max(24px, env(safe-area-inset-bottom)); width: 176px; height: 174px; pointer-events: none; }
  .touch-btn { position: absolute; pointer-events: auto; border-radius: 50%; border: 1px solid rgba(217,235,252,.27); background: rgba(10,20,35,.62); color: rgba(235,244,253,.8); display: flex; flex-direction: column; align-items: center; justify-content: center; line-height: 1; box-shadow: 0 3px 14px rgba(0,0,0,.3); touch-action: none; backdrop-filter: blur(4px); }
  .touch-btn small { font-size: 5px; letter-spacing: .06em; color: rgba(207,224,243,.46); margin-top: 2px; }
  .touch-btn.attack { right: 2px; bottom: 4px; width: 70px; height: 70px; font-size: 22px; border-color: rgba(216,184,120,.58); background: radial-gradient(circle at 40% 35%, rgba(111,86,48,.76), rgba(25,34,44,.75)); color: var(--gold-bright); }
  .touch-btn.small { width: 48px; height: 48px; font-size: 15px; }
  #btn-jump { right: 79px; bottom: 63px; }
  #btn-interact { right: 129px; bottom: 16px; }
  #btn-block { right: 6px; bottom: 83px; }
  #btn-spell { right: 79px; bottom: 118px; }
  #btn-sprint { right: 131px; bottom: 73px; width: 40px; height: 40px; font-size: 13px; }
  .hud-top-left { top: 13px; left: 12px; transform: scale(.78); transform-origin: top left; }
  .compass-wrap { top: 10px; width: 38vw; opacity: .8; }
  .hud-top-right { top: 12px; right: 11px; }
  .map-frame { width: 76px; height: 76px; }
  .quest-tracker { display: none; }
  .hud-bottom-left { display: none; }
  .hud-bottom-right { right: 12px; bottom: 208px; flex-direction: column; }
  .round-action { width: 34px; height: 34px; font-size: 10px; }
  .round-action small { display: none; }
  .hud-bottom-center { bottom: 128px; width: 100%; }
  .hotbar { gap: 2px; padding: 3px; }
  .slot { width: 39px; height: 42px; }
  .slot-icon { font-size: 14px; } .slot small { display: none; }
  .spell-cost { display: none; }
  .interact-prompt { bottom: 185px; font-size: 10px; }
  .crosshair { opacity: .48; }
  .companion-card { right: 12px; bottom: 250px; }
  .location-title { top: 17%; }
  .menu-top { padding: 16px 20px; }
  .menu-top-right #menu-clock { display: none; }
  .menu-main { display: flex; flex-direction: column; justify-content: center; gap: 18px; padding: 0 18px; }
  .hero-copy { max-width: 100%; text-align: center; }
  .eyebrow { justify-content: center; font-size: 7px; margin-bottom: 12px; }
  .logo { font-size: clamp(43px, 13vw, 68px); }
  .logo-cat { width: 45px; height: 24px; margin: 0 auto 5px; }
  .hero-copy h2 { font-size: 9px; letter-spacing: .38em; margin-top: 10px; }
  .hero-lede, .hero-facts { display: none; }
  .character-panel { width: min(440px, 100%); padding: 16px 18px 15px; }
  .panel-heading { margin-bottom: 10px; }
  .field-label { margin-top: 9px; }
  .name-input { padding: 6px 10px 5px; font-size: 16px; }
  .breed-card, .class-card { padding: 6px; }
  .breed-swatch { width: 20px; height: 24px; flex-basis: 20px; }
  .breed-card b, .class-card b { font-size: 9px; }
  .breed-card small, .class-card small { display: none; }
  .fur-row { margin-top: 8px; }
  .play-button { margin-top: 13px; padding: 8px 12px; font-size: 19px; }
  .menu-footnote { display: none; }
  .menu-footer { display: none; }
  .grain { opacity: .02; }
  #dialogue { padding: 10px; align-items: flex-end; }
  .dialogue-box { grid-template-columns: 70px 1fr; }
  .dialogue-portrait { min-height: 90px; font-size: 28px; }
  .dialogue-text { font-size: 12px; max-height: 100px; overflow: auto; }
  .book-panel { width: 96vw; max-height: 88vh; }
  .inventory-body, .shop-body, .quest-body { grid-template-columns: 1fr; overflow: auto; }
  .inventory-right { border-left: 0; border-top: 1px solid var(--line); }
  .quest-list { display: flex; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--line); }
  .quest-list button { min-width: 160px; border-left: 0; border-bottom: 2px solid transparent; }
  .quest-list button.active { border-left: 0; border-bottom-color: var(--gold); }
  .pause-panel { width: 92vw; }
  .pause-controls { display: none; }
}

@media (max-height: 760px) and (min-width: 821px) {
  .logo { font-size: 78px; }
  .hero-lede { margin-top: 18px; font-size: 14px; }
  .hero-facts { margin-top: 20px; }
  .character-panel { padding: 18px 22px; }
  .field-label { margin-top: 10px; }
  .menu-top { padding-top: 18px; padding-bottom: 10px; }
  .menu-footer { padding-top: 10px; padding-bottom: 14px; }
}

/* ============ MODALS ============ */
.modal-layer { position: absolute; inset: 0; z-index: 30; display: flex; align-items: center; justify-content: center; padding: 30px; background: rgba(3,8,15,.58); backdrop-filter: blur(7px); }
.book-panel, .dialogue-box, .pause-panel, .map-panel, .death-panel {
  background: linear-gradient(150deg, rgba(18,30,47,.97), rgba(7,14,25,.98));
  border: 1px solid rgba(210,229,248,.18); box-shadow: 0 30px 100px rgba(0,0,0,.7), inset 0 1px 0 rgba(255,255,255,.05);
  position: relative;
}
.book-panel::before, .dialogue-box::before, .pause-panel::before, .map-panel::before {
  content: ""; position: absolute; inset: 7px; border: 1px solid rgba(216,184,120,.1); pointer-events: none;
}
.book-panel { width: min(940px, 94vw); max-height: 84vh; display: flex; flex-direction: column; }
.book-tabs { display: flex; align-items: center; gap: 2px; padding: 12px 16px 0; border-bottom: 1px solid var(--line); }
.book-tab { padding: 9px 16px 11px; border: 0; border-bottom: 2px solid transparent; background: transparent; color: var(--faint); font-size: 8px; letter-spacing: .22em; }
.book-tab:hover { color: var(--muted); }
.book-tab.active { color: var(--gold-bright); border-bottom-color: var(--gold); }
.book-close { margin-left: auto; width: 30px; height: 30px; border: 1px solid rgba(202,224,245,.14); background: transparent; color: var(--muted); font-size: 18px; line-height: 1; }
