.journal-date { margin-left: auto; margin-right: 15px; font-family: var(--serif); font-size: 10px; color: var(--faint); font-style: italic; }
.inventory-body { display: grid; grid-template-columns: 1fr 270px; min-height: 400px; overflow: hidden; }
.inventory-left { padding: 22px; }
.panel-title { font-family: var(--serif); font-size: 12px; letter-spacing: .17em; color: var(--gold); margin-bottom: 17px; }
.inventory-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 7px; }
.item-card { position: relative; min-height: 70px; border: 1px solid rgba(199,220,242,.12); background: rgba(12,22,37,.5); padding: 8px 6px 6px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; transition: .15s; }
.item-card:hover { border-color: rgba(216,184,120,.45); background: rgba(26,41,60,.65); }
.item-card.selected { border-color: rgba(216,184,120,.62); background: rgba(55,48,34,.42); }
.item-icon { font-family: var(--serif); font-size: 24px; color: var(--gold); line-height: 1; text-shadow: 0 0 14px rgba(216,184,120,.15); }
.item-name { font-size: 7px; text-align: center; color: var(--muted); line-height: 1.2; }
.item-count { position: absolute; top: 3px; right: 5px; font-size: 7px; color: var(--gold-bright); }
.item-card.quest { border-color: rgba(163,139,209,.36); }
.item-detail { margin-top: 18px; min-height: 76px; padding: 11px 13px; border: 1px solid rgba(197,219,241,.1); background: rgba(4,10,18,.34); font-family: var(--serif); font-size: 11px; line-height: 1.55; color: var(--muted); }
.item-detail b { color: var(--gold-bright); font-weight: 400; font-size: 13px; }
.item-detail .detail-actions { margin-top: 8px; display: flex; gap: 5px; }
.detail-actions button, .shop-buy { border: 1px solid rgba(216,184,120,.35); background: rgba(216,184,120,.08); color: var(--gold-bright); font-size: 7px; letter-spacing: .12em; padding: 5px 9px; }
.detail-actions button:hover, .shop-buy:hover { background: rgba(216,184,120,.18); }
.inventory-right { border-left: 1px solid var(--line); padding: 22px; background: rgba(5,11,20,.28); }
.equip-title { font-size: 8px; letter-spacing: .22em; color: var(--faint); margin-bottom: 11px; }
.equip-slots { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.equip-slot { min-height: 48px; border: 1px solid rgba(195,217,240,.11); padding: 7px; font-size: 7px; color: var(--faint); display: flex; flex-direction: column; gap: 3px; background: rgba(11,21,36,.4); }
.equip-slot b { font-family: var(--serif); font-weight: 400; font-size: 9px; color: var(--muted); }
.equip-slot .equip-icon { font-size: 15px; color: var(--gold); }
.character-summary { margin-top: 17px; padding-top: 12px; border-top: 1px solid var(--line); }
.summary-row { display: flex; justify-content: space-between; padding: 5px 0; font-size: 8px; color: var(--faint); }
.summary-row b { font-family: var(--serif); font-weight: 400; font-size: 11px; color: var(--ink); }
.xp-block { margin-top: 14px; }
.xp-block > span { font-size: 7px; letter-spacing: .17em; color: var(--faint); }
.xp-block > span b { color: var(--gold-bright); font-size: 11px; }
.xp-track { height: 4px; background: rgba(255,255,255,.07); margin: 6px 0 4px; }
.xp-track i { display: block; height: 100%; background: linear-gradient(90deg, var(--gold-deep), var(--gold-bright)); }
.xp-block small { font-size: 7px; color: var(--faint); }
.skill-points { margin-top: 14px; padding: 8px; border: 1px dashed rgba(216,184,120,.28); text-align: center; font-family: var(--serif); font-size: 10px; color: var(--gold); }
.skills-pane { padding: 22px; overflow: auto; }
.skill-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
.skill-card { border: 1px solid rgba(198,219,242,.12); background: rgba(11,21,36,.45); padding: 13px 14px; display: flex; align-items: center; gap: 12px; }
.skill-glyph { width: 38px; height: 38px; display: grid; place-items: center; border: 1px solid rgba(216,184,120,.25); border-radius: 50%; font-size: 17px; color: var(--gold); }
