.dialogue-portrait { position: relative; min-height: 170px; border: 1px solid rgba(216,184,120,.17); background: radial-gradient(circle at 50% 42%, rgba(66,85,106,.75), rgba(10,20,34,.9)); display: grid; place-items: center; font-size: 55px; color: var(--gold); text-shadow: 0 0 25px rgba(216,184,120,.25); overflow: hidden; }
.dialogue-portrait::before { content: ""; position: absolute; inset: 6px; border: 1px solid rgba(216,184,120,.09); }
.dialogue-content { padding: 7px 8px 5px 0; display: flex; flex-direction: column; }
.dialogue-name { font-family: var(--serif); font-size: 22px; letter-spacing: .06em; color: var(--gold-bright); }
.dialogue-role { font-size: 7px; letter-spacing: .2em; color: var(--faint); text-transform: uppercase; margin-top: 3px; }
.dialogue-text { font-family: var(--serif); font-size: 15px; line-height: 1.65; color: rgba(228,237,247,.83); margin: 14px 0 16px; min-height: 48px; }
.dialogue-options { display: flex; flex-direction: column; gap: 5px; }
.dialogue-option { text-align: left; padding: 8px 11px; border: 1px solid rgba(200,222,244,.12); background: rgba(9,18,31,.45); color: var(--muted); font-family: var(--serif); font-size: 12px; transition: .14s; }
.dialogue-option:hover { border-color: rgba(216,184,120,.4); background: rgba(55,48,34,.28); color: var(--ink); padding-left: 15px; }
.dialogue-option.quest { color: var(--gold-bright); }
.dialogue-option.leave { color: var(--faint); font-size: 10px; }
.dialogue-relation { margin-top: auto; padding-top: 12px; display: flex; align-items: center; gap: 10px; }
.dialogue-relation span { font-size: 6px; letter-spacing: .17em; color: var(--faint); }
.relation-track { flex: 1; height: 3px; background: rgba(255,255,255,.07); }
.relation-track i { display: block; height: 100%; width: 20%; background: linear-gradient(90deg, #7d5e39, var(--gold)); }

/* quest log */
.quest-body { display: grid; grid-template-columns: 230px 1fr; min-height: 400px; }
.quest-list { border-right: 1px solid var(--line); padding: 12px 0; background: rgba(5,11,20,.25); }
.quest-list button { display: block; width: 100%; text-align: left; padding: 12px 18px; border: 0; border-left: 2px solid transparent; background: transparent; color: var(--muted); }
.quest-list button:hover { background: rgba(255,255,255,.025); }
.quest-list button.active { border-left-color: var(--gold); background: rgba(216,184,120,.055); }
.quest-list b { display: block; font-family: var(--serif); font-size: 13px; font-weight: 400; }
.quest-list small { display: block; font-size: 6px; letter-spacing: .16em; color: var(--faint); margin-top: 3px; }
.quest-list .done { color: var(--faint); text-decoration: line-through; opacity: .6; }
.quest-detail { padding: 30px 34px; }
.quest-detail-kicker { font-size: 7px; letter-spacing: .26em; color: var(--gold); }
.quest-detail h3 { font-family: var(--serif); font-size: 30px; font-weight: 400; margin: 8px 0 13px; letter-spacing: .02em; }
.quest-detail > p { font-family: var(--serif); font-size: 13px; line-height: 1.7; color: var(--muted); max-width: 520px; }
.quest-objectives { margin: 23px 0; display: flex; flex-direction: column; gap: 8px; }
.objective { display: flex; gap: 9px; align-items: flex-start; font-size: 10px; color: var(--muted); line-height: 1.5; }
.objective i { width: 10px; height: 10px; margin-top: 1px; border: 1px solid rgba(216,184,120,.38); transform: rotate(45deg); flex: 0 0 10px; }
.objective.done { color: var(--faint); text-decoration: line-through; }
.objective.done i { background: var(--gold); box-shadow: 0 0 7px rgba(216,184,120,.4); }
.quest-reward { display: inline-block; margin-top: 5px; padding: 9px 13px; border: 1px solid rgba(216,184,120,.18); font-size: 8px; letter-spacing: .08em; color: var(--gold); }

/* shop */
.shop-body { display: grid; grid-template-columns: 1fr 280px; min-height: 400px; }
.shop-list { padding: 17px; display: flex; flex-direction: column; gap: 5px; overflow: auto; }
.shop-row { display: flex; align-items: center; gap: 11px; padding: 9px 11px; border: 1px solid rgba(199,220,242,.1); background: rgba(10,19,32,.38); }
.shop-row:hover { border-color: rgba(216,184,120,.32); }
.shop-icon { width: 34px; height: 34px; display: grid; place-items: center; border: 1px solid rgba(216,184,120,.17); color: var(--gold); font-family: var(--serif); font-size: 18px; }
.shop-row div { flex: 1; }
.shop-row b { display: block; font-family: var(--serif); font-size: 12px; font-weight: 400; }
.shop-row small { display: block; font-size: 7px; color: var(--faint); margin-top: 2px; }
.shop-price { font-family: var(--serif); color: var(--gold-bright); font-size: 12px; margin-right: 8px; }
.shop-buy { white-space: nowrap; }
.shop-side { border-left: 1px solid var(--line); padding: 25px 22px; background: rgba(5,11,20,.25); }
.merchant-portrait { font-size: 42px; color: var(--gold); margin-bottom: 10px; text-shadow: 0 0 24px rgba(216,184,120,.25); }
.shop-side h3 { font-family: var(--serif); font-weight: 400; font-size: 22px; margin: 0 0 10px; }
.shop-side p { font-family: var(--serif); font-size: 12px; font-style: italic; line-height: 1.6; color: var(--muted); }
.shop-tip { margin-top: 22px; font-size: 7px; line-height: 1.5; color: var(--faint); border-top: 1px solid var(--line); padding-top: 11px; }

/* world map */
.map-panel { width: min(940px, 94vw); padding: 18px; }
.map-header { display: flex; align-items: center; justify-content: space-between; padding: 3px 3px 13px; font-family: var(--serif); font-size: 12px; letter-spacing: .24em; color: var(--gold); }
