#worldmap-canvas { display: block; width: 100%; height: auto; max-height: 62vh; object-fit: contain; background: #0a1522; border: 1px solid rgba(200,222,245,.13); }
.map-legend { display: flex; gap: 20px; padding: 12px 4px 0; font-size: 7px; letter-spacing: .12em; color: var(--faint); }
.map-legend span { display: flex; align-items: center; gap: 6px; }
