.menu-button { display: block; width: 100%; padding: 11px; margin: 6px 0; border: 1px solid rgba(205,226,247,.15); background: rgba(14,26,43,.5); color: var(--muted); font-family: var(--serif); font-size: 14px; letter-spacing: .05em; transition: .15s; }
.menu-button:hover { border-color: rgba(216,184,120,.45); color: var(--gold-bright); background: rgba(50,45,34,.28); }
.menu-button.primary { border-color: rgba(216,184,120,.58); background: linear-gradient(100deg, rgba(155,121,65,.5), rgba(86,68,41,.4)); color: var(--gold-bright); }
.menu-button.subtle { margin-top: 18px; border-color: transparent; background: transparent; color: var(--faint); font-size: 10px; }
.pause-controls { margin-top: 22px; padding-top: 16px; border-top: 1px solid var(--line); display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; text-align: left; font-size: 7px; color: var(--faint); }
.pause-controls kbd { margin-right: 3px; }
.settings-row { margin-top: 15px; padding-top: 15px; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 9px; text-align: left; font-size: 8px; color: var(--faint); }
.settings-row label { display: flex; align-items: center; gap: 9px; }
.settings-row input { flex: 1; accent-color: var(--gold); }

/* death */
#death { z-index: 35; background: radial-gradient(ellipse at center, rgba(45,10,14,.45), rgba(3,6,12,.92)); }
.death-panel { width: min(460px, 90vw); padding: 38px; text-align: center; border-color: rgba(174,73,73,.28); }
.death-mark { font-size: 38px; color: #a96b64; opacity: .8; }
.death-eyebrow { margin-top: 14px; font-size: 7px; letter-spacing: .3em; color: #b57b72; }
.death-panel h2 { font-family: var(--serif); font-weight: 400; font-size: 34px; margin: 8px 0 13px; letter-spacing: .07em; }
.death-panel p { font-family: var(--serif); font-size: 13px; line-height: 1.6; color: var(--muted); margin-bottom: 20px; }

/* subtitles & bubbles */
.subtitle { position: absolute; left: 50%; bottom: 156px; transform: translateX(-50%); max-width: 70vw; padding: 7px 15px; background: rgba(3,8,15,.72); border-left: 2px solid rgba(216,184,120,.4); font-family: var(--serif); font-size: 13px; color: rgba(236,244,252,.9); z-index: 12; text-align: center; pointer-events: none; }
#bubble-layer { position: absolute; inset: 0; z-index: 9; pointer-events: none; overflow: hidden; }
.world-bubble { position: absolute; transform: translate(-50%, -100%); padding: 5px 9px; background: rgba(7,14,25,.82); border: 1px solid rgba(210,229,248,.18); font-family: var(--serif); font-size: 10px; color: rgba(233,241,250,.9); white-space: nowrap; opacity: 0; transition: opacity .3s; backdrop-filter: blur(4px); }
.world-bubble.show { opacity: 1; }
.world-bubble::after { content: ""; position: absolute; left: 50%; bottom: -4px; width: 7px; height: 7px; transform: translateX(-50%) rotate(45deg); background: rgba(7,14,25,.82); border-right: 1px solid rgba(210,229,248,.18); border-bottom: 1px solid rgba(210,229,248,.18); }
.world-bubble.important { border-color: rgba(216,184,120,.38); color: var(--gold-bright); }

/* scrollbars */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: rgba(255,255,255,.03); }
::-webkit-scrollbar-thumb { background: rgba(185,206,229,.18); }

@media (max-width: 480px) {
  .logo { font-size: 47px; }
  .character-panel { padding: 13px 13px 12px; }
  .class-glyph { display: none; }
  .breed-card b, .class-card b { font-size: 8px; }
  .hotbar .slot { width: 36px; height: 39px; }
  .slot-icon { font-size: 13px; }
  .hud-bottom-center { bottom: 120px; }
  .joystick { width: 100px; height: 100px; }
  .touch-actions { transform: scale(.92); transform-origin: bottom right; }
}

import * as THREE from 'three';

export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const rand = (min, max) => min + Math.random() * (max - min);
export const randi = (min, max) => Math.floor(rand(min, max + 1));
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
export const TAU = Math.PI * 2;

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hash2(x, y) {
  let h = x * 374761393 + y * 668265263;
  h = (h ^ (h >> 13)) * 1274126177;
  return ((h ^ (h >> 16)) >>> 0) / 4294967295;
}

export function valueNoise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi), b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1);
  return lerp(lerp(a, b, u), lerp(c, d, u), v);
}

export function fbm(x, y, octaves = 4) {
  let sum = 0, amp = 0.5, freq = 1, norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += amp * valueNoise(x * freq, y * freq);
    norm += amp;
    amp *= 0.5; freq *= 2.03;
  }
  return sum / norm;
}

export function makeRadialTexture(color = '255,255,255', inner = 0.15, size = 64) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, `rgba(${color},1)`);
  g.addColorStop(inner, `rgba(${color},.8)`);
  g.addColorStop(1, `rgba(${color},0)`);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function makeGlowTexture(color = '255,210,140') {
  return makeRadialTexture(color, 0.08, 128);
}

export function makeTextSprite(text, opts = {}) {
  const {
    color = '#e9eef7', font = '600 34px Georgia', padding = 18,
    background = 'rgba(6,12,22,.75)', border = 'rgba(216,184,120,.4)', scale = 1
  } = opts;
  const c = document.createElement('canvas');
  const ctx = c.getContext('2d');
  ctx.font = font;
  const metrics = ctx.measureText(text);
  c.width = Math.ceil(metrics.width + padding * 2);
  c.height = 64;
  const g = c.getContext('2d');
  g.fillStyle = background;
  g.fillRect(0, 0, c.width, c.height);
  g.strokeStyle = border;
  g.lineWidth = 2;
  g.strokeRect(1, 1, c.width - 2, c.height - 2);
  g.font = font;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillStyle = color;
  g.fillText(text, c.width / 2, c.height / 2 + 1);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(c.width / 64 * scale, c.height / 64 * scale, 1);
  return sprite;
}

export function makePawPrintTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d');
  g.fillStyle = 'rgba(21,34,50,.42)';
  g.beginPath(); g.ellipse(32, 39, 12, 15, 0, 0, TAU); g.fill();
  for (let i = 0; i < 4; i++) {
    const a = -Math.PI * 0.78 + i * 0.36;
    g.beginPath(); g.ellipse(32 + Math.cos(a) * 18, 27 + Math.sin(a) * 12, 5, 7, a + Math.PI / 2, 0, TAU); g.fill();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function seededPoint(rng, minX, maxX, minZ, maxZ) {
  return { x: lerp(minX, maxX, rng()), z: lerp(minZ, maxZ, rng()) };
}

export function formatTime(hours) {
  const h = Math.floor(hours) % 24;
  const m = Math.floor((hours % 1) * 60);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

export function disposeGroup(group) {
  group.traverse(o => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach(m => { if (m.map) m.map.dispose(); m.dispose(); });
    }
  });
}
